const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');
test('actual Seaside presets keep seven services on dry land with immutable source cards',async()=>{
 const {settlementDistrictEntries}=await import('../settlement-districts.js'),{seasideRecipe,SEASIDE_SCENES}=await import('../seaside-scenes.js'),{domesticRecipe,DOMESTIC_SCENES}=await import('../domestic-scenes.js'),{planSettlementPreset}=await import('../settlement-layout.js'),{evolveBoardEconomy,resolveBoardEconomy}=await import('../board-economy.js'),{createJoinVerifier}=await import('../board-join-verifier.js');
 const root=path.join(__dirname,'..'),assetIndex={...JSON.parse(fs.readFileSync(path.join(root,'domestic-assets/index.json'),'utf8')),...JSON.parse(fs.readFileSync(path.join(root,'coastal-assets/index.json'),'utf8'))},catalog=JSON.parse(fs.readFileSync(path.join(root,'simulation-assets/catalog.json'),'utf8')),parts=JSON.parse(fs.readFileSync(path.join(root,catalog.find(x=>x.id==='tree-standing').json),'utf8')),xs=[],zs=[];for(const p of parts)for(let i=0;i<p.positions.length;i+=3){xs.push(p.positions[i]);zs.push(p.positions[i+2]);}const dimensions={'tree-standing':{w:2*(Math.max(...xs)-Math.min(...xs)),d:2*(Math.max(...zs)-Math.min(...zs))}};
 for(const preset of ['landing','salt','repair']){
  const entries=settlementDistrictEntries('seaside');entries[0].preset=preset;const cards=entries.map((e,i)=>({id:e.type+'-'+i,revision:1,rendition:{meshes:[]},cells:[{q:0,r:0}],recipe:e.type==='seaside'?seasideRecipe(e.preset,e.seed):domesticRecipe(e.type,e.preset,e.seed),capabilities:(SEASIDE_SCENES[e.type]||DOMESTIC_SCENES[e.type]).capabilities})),before=structuredClone(cards),result=planSettlementPreset({cards,entries,assetIndex,dimensions});
  assert.equal(result.status,'ready',JSON.stringify(result.warnings));assert.deepEqual(result.site,{q:-4,r:4});assert.equal(result.attempts.length,1);assert.equal(result.perCard.filter(c=>c.status==='connected').length,7);assert.deepEqual(result.warnings,[]);assert.deepEqual(cards,before);for(const c of cards)assert.equal(result.board.cards[c.id+'@1'],c);
  const coast=result.heightAt.coasts[0],plan=result.assembly.plans.find(p=>p.type==='seaside');assert.equal(coast.id,plan.id);assert.equal(coast.wetPolygon.length,5);assert(Number.isFinite(coast.waterLevel));assert.equal(plan.placements[0].items.filter(i=>i.asset==='CE-031').length,4);
  for(const p of plan.paths)for(let i=1;i<p.points.length;i++){const world=v=>({x:plan.center.x+v.x,z:plan.center.z+v.z});assert(result.heightAt.coversDryCorridor(world(p.points[i-1]),world(p.points[i]),.6));}
  const wet={x:plan.center.x,z:plan.center.z+25};assert(result.heightAt.isWater(wet.x,wet.z));assert(result.heightAt.cached.isWater(wet.x,wet.z));assert.equal(result.heightAt.cached(wet.x,wet.z),result.heightAt(wet.x,wet.z));
  const verify=createJoinVerifier({boardId:result.board.id,boardRevision:result.board.revision,heightAt:result.heightAt.cached,contains:()=>true,obstacles:[],obstaclesComplete:true}),a={...wet,y:result.heightAt(wet.x,wet.z)},b={x:wet.x+1,z:wet.z,y:result.heightAt(wet.x+1,wet.z)};assert.equal(verify({signature:'decorative-boat-is-not-a-bridge',access:{a,b}},result.board),null);
  let board=evolveBoardEconomy(result.board,result.economy,'supplies'),economy=resolveBoardEconomy(board,result.assembly,result.heightAt,assetIndex,dimensions);board=evolveBoardEconomy(board,economy,'day',{days:6});economy=resolveBoardEconomy(board,result.assembly,result.heightAt,assetIndex,dimensions);assert(economy.report.goals.every(g=>g.ready));assert.equal(economy.report.population,6);assert.equal(economy.report.capacities.housing,6);assert.equal(economy.report.stock.clay,18);
  const inland=planSettlementPreset({cards,entries,assetIndex,dimensions,sites:[{q:-4,r:3}]});assert.equal(inland.status,'blocked');assert(inland.attempts[0].warnings.some(w=>/Seaward edges/.test(w.reason)));
 }
});
